import 'package:flutter/material.dart';\nimport 'package:provider/provider.dart';\nimport '../constants/strings.dart';\nimport '../providers/ai_tools_provider.dart';\nimport '../widgets/ai_tool_card.dart';\n\nclass CategoriesScreen extends StatefulWidget {\n  const CategoriesScreen({Key? key}) : super(key: key);\n\n  @override\n  State<CategoriesScreen> createState() => _CategoriesScreenState();\n}\n\nclass _CategoriesScreenState extends State<CategoriesScreen> {\n  String? _selectedCategory;\n\n  @override\n  Widget build(BuildContext context) {\n    return Consumer<AIToolsProvider>(\n      builder: (context, toolsProvider, _) {\n        final categories = toolsProvider.getCategories();\n        final tools = _selectedCategory != null\n            ? toolsProvider.getToolsBySpecificCategory(_selectedCategory!)\n            : toolsProvider.allTools;\n\n        return Scaffold(\n          appBar: AppBar(\n            title: Text(AppStrings.categories),\n          ),\n          body: Column(\n            children: [\n              Padding(\n                padding: const EdgeInsets.all(16),\n                child: SingleChildScrollView(\n                  scrollDirection: Axis.horizontal,\n                  child: Row(\n                    children: [\n                      GestureDetector(\n                        onTap: () => setState(() => _selectedCategory = null),\n                        child: Container(\n                          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),\n                          decoration: BoxDecoration(\n                            color: _selectedCategory == null\n                                ? Theme.of(context).primaryColor\n                                : Colors.grey[300],\n                            borderRadius: BorderRadius.circular(20),\n                          ),\n                          child: Text(\n                            'All',\n                            style: TextStyle(\n                              color: _selectedCategory == null ? Colors.white : Colors.black,\n                            ),\n                          ),\n                        ),\n                      ),\n                      ...categories.map((category) {\n                        final isSelected = _selectedCategory == category;\n                        return Padding(\n                          padding: const EdgeInsets.only(left: 8),\n                          child: GestureDetector(\n                            onTap: () => setState(() => _selectedCategory = category),\n                            child: Container(\n                              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),\n                              decoration: BoxDecoration(\n                                color: isSelected\n                                    ? Theme.of(context).primaryColor\n                                    : Colors.grey[300],\n                                borderRadius: BorderRadius.circular(20),\n                              ),\n                              child: Text(\n                                category,\n                                style: TextStyle(\n                                  color: isSelected ? Colors.white : Colors.black,\n                                ),\n                              ),\n                            ),\n                          ),\n                        );\n                      }).toList(),\n                    ],\n                  ),\n                ),\n              ),\n              Expanded(\n                child: GridView.builder(\n                  padding: const EdgeInsets.all(16),\n                  gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(\n                    crossAxisCount: 2,\n                    childAspectRatio: 0.85,\n                    mainAxisSpacing: 16,\n                    crossAxisSpacing: 16,\n                  ),\n                  itemCount: tools.length,\n                  itemBuilder: (context, index) {\n                    return AIToolCard(tool: tools[index]);\n                  },\n                ),\n              ),\n            ],\n          ),\n        );\n      },\n    );\n  }\n}\n